insert into public.writing_prompts (title_he, prompt_en, cefr_level, sort_order)
select w.title_he, w.prompt_en, w.lvl::cefr_level, w.sort_order
from (values
  ('המשפחה שלי', 'Write 3-5 sentences about your family. Who is in it, and what do they like doing?', 'A1', 100),
  ('החיה האהובה עליי', 'Write 3-5 sentences about an animal you like. What does it look like, and why do you like it?', 'A1', 101),
  ('מזג האוויר היום', 'Write 3-4 sentences about the weather today and what you want to do.', 'A1', 102),
  ('השכונה שלי', 'Describe your street or neighborhood in 3-5 sentences. What is there? Is it quiet or busy?', 'A1', 103),
  ('יום ההולדת שלי', 'Write 3-5 sentences about your birthday. When is it, and how do you like to celebrate?', 'A1', 104),
  ('הטיול הבא', 'Write about a trip you want to take. Where will you go, who with, and what are you going to do there?', 'A2', 105),
  ('מתכון פשוט', 'Explain how to make a simple dish you know. Use the words first, then, after that and finally.', 'A2', 106),
  ('חברות טובה', 'Describe a good friend. How did you meet, what are they like, and what do you do together?', 'A2', 107),
  ('הודעה על איחור', 'Write a short message to your teacher or manager. Explain that you will be late tomorrow and why.', 'A2', 108),
  ('קנייה אחרונה', 'Write about something you bought recently. Where did you buy it, how much did it cost, and are you happy with it?', 'A2', 109),
  ('בעיה ופתרון', 'Describe a problem you had and how you solved it. What did you learn from it?', 'B1', 110),
  ('מייל לשותפים בדירה', 'Write an email to a roommate about a problem in the apartment, like noise or cleaning. Suggest a fair solution.', 'B1', 111),
  ('שינוי גדול', 'Write about a big change in your life, like moving, a new job or a new school. How did it feel at first, and how do you feel now?', 'B1', 112),
  ('בעד ונגד: רשתות חברתיות לבני נוער', 'Should teenagers use social media? Give two advantages and two disadvantages, then your opinion.', 'B1', 113),
  ('המלצה על מקום לאכול', 'Recommend a restaurant or café to a friend. Describe the food, the atmosphere and the prices.', 'B1', 114),
  ('מכתב מועמדות', 'Write a cover letter for a job or volunteer role you would like. Explain why you are a good fit, with examples.', 'B2', 115),
  ('תחבורה ציבורית בחינם?', 'Should public transport be free? Write an essay that considers both sides and ends with a clear conclusion.', 'B2', 116),
  ('דוח קצר', 'Write a short report for a manager or teacher about a problem at work or school, with two recommendations.', 'B2', 117),
  ('כתבה על אירוע', 'Write a short news article about an event in your area. Answer who, what, when, where and why.', 'B2', 118),
  ('לשנות דבר אחד בבית הספר', 'If you could change one thing about the school system, what would it be? Explain why and how it would work.', 'B2', 119),
  ('סקירה ביקורתית', 'Write a critical review of an app or service you use. Evaluate its strengths and weaknesses and suggest improvements.', 'C1', 120),
  ('שבוע עבודה של ארבעה ימים', 'Write an article arguing for or against a four-day working week. Support your view with evidence and answer the main objections.', 'C1', 121),
  ('מייל רשמי לרשות ציבורית', 'Write a formal email to a public body raising a concern about a local issue. Keep the tone polite but firm.', 'C1', 122),
  ('סיכום של מחקר', 'Summarize the key findings of an article or study you read recently, and explain why they matter.', 'C1', 123),
  ('סיפור קצר', 'Write a short story that begins with the sentence: "The message arrived three hours too late."', 'C1', 124),
  ('חופש הביטוי וגבולותיו', 'Discuss where the limits of free speech should lie. Weigh competing principles and reach a nuanced conclusion.', 'C2', 125),
  ('לפרק טיעון', 'Choose a common argument you disagree with. Present it fairly, then take it apart point by point.', 'C2', 126),
  ('מכתב למערכת', 'Write a letter to the editor responding to a recent public debate. Use a measured, persuasive register.', 'C2', 127),
  ('ניתוח מגמה', 'Analyze a social or technological trend of the last decade: its causes, its consequences and where it may lead.', 'C2', 128),
  ('מסה אישית', 'Write a reflective essay about a belief you once held firmly and later changed. What changed your mind?', 'C2', 129)
) as w(title_he, prompt_en, lvl, sort_order)
where not exists (select 1 from public.writing_prompts p where p.prompt_en = w.prompt_en);

insert into public.idioms_phrasal_verbs (phrase, type, meaning_he, example_en, cefr_level, sort_order)
select i.phrase, i.type::idiom_type, i.meaning_he, i.example_en, i.lvl::cefr_level, i.sort_order
from (values
  ('turn on', 'phrasal_verb', 'להדליק', 'Can you turn on the light, please?', 'A1', 100),
  ('turn off', 'phrasal_verb', 'לכבות', 'Please turn off your phone in the cinema.', 'A1', 101),
  ('sit down', 'phrasal_verb', 'לשבת', 'Please sit down and wait for your name.', 'A1', 102),
  ('come back', 'phrasal_verb', 'לחזור', 'When do you come back from Paris?', 'A1', 103),
  ('put on', 'phrasal_verb', 'ללבוש', 'Put on your coat. It''s cold outside.', 'A1', 104),
  ('wake up', 'phrasal_verb', 'להתעורר', 'I wake up at six every morning.', 'A1', 105),
  ('pick up', 'phrasal_verb', 'לאסוף (מישהו או משהו)', 'I''ll pick you up from the station at five.', 'A2', 106),
  ('check in', 'phrasal_verb', 'לעשות צ''ק-אין במלון או בטיסה', 'We checked in at the hotel at three.', 'A2', 107),
  ('throw away', 'phrasal_verb', 'לזרוק', 'Don''t throw away that box. I need it.', 'A2', 108),
  ('in a hurry', 'idiom', 'בלחץ זמן, ממהרים', 'Sorry, I can''t talk now. I''m in a hurry.', 'A2', 109),
  ('make up your mind', 'idiom', 'להחליט', 'You have to make up your mind by Friday.', 'A2', 110),
  ('keep an eye on', 'idiom', 'לשים עין על', 'Can you keep an eye on my bag for a minute?', 'A2', 111),
  ('run out of', 'phrasal_verb', 'שנגמר למישהו משהו', 'We''ve run out of milk. Can you buy some?', 'B1', 112),
  ('set up', 'phrasal_verb', 'להקים, לארגן', 'She set up her own business when she was 25.', 'B1', 113),
  ('take after', 'phrasal_verb', 'להיות דומים להורה', 'He takes after his mother. They both love music.', 'B1', 114),
  ('the last straw', 'idiom', 'הקש ששבר את גב הגמל', 'When he was late again, it was the last straw.', 'B1', 115),
  ('get cold feet', 'idiom', 'להתחרט ברגע האחרון מפחד', 'He got cold feet the night before the interview.', 'B1', 116),
  ('in the long run', 'idiom', 'בטווח הארוך', 'Good shoes save you money in the long run.', 'B1', 117),
  ('put up with', 'phrasal_verb', 'לסבול, להשלים עם', 'I can''t put up with this noise any longer.', 'B2', 118),
  ('back up', 'phrasal_verb', 'לגבות (קבצים); לתמוך במישהו', 'Always back up your files before an update.', 'B2', 119),
  ('cut down on', 'phrasal_verb', 'לצמצם', 'I''m trying to cut down on sugar.', 'B2', 120),
  ('a drop in the ocean', 'idiom', 'טיפה בים', 'The donation is welcome, but it''s a drop in the ocean.', 'B2', 121),
  ('on the fence', 'idiom', 'מתלבטים, עוד לא החליטו', 'I''m still on the fence about the new job offer.', 'B2', 122),
  ('jump to conclusions', 'idiom', 'להסיק מסקנות מהר מדי', 'Don''t jump to conclusions before you hear the whole story.', 'B2', 123),
  ('phase out', 'phrasal_verb', 'להוציא משימוש בהדרגה', 'The city will phase out diesel buses by 2030.', 'C1', 124),
  ('rule out', 'phrasal_verb', 'לשלול אפשרות', 'The doctors haven''t ruled out an infection.', 'C1', 125),
  ('a gray area', 'idiom', 'שטח אפור', 'Using drones over private homes is still a legal gray area.', 'C1', 126),
  ('go the extra mile', 'idiom', 'להתאמץ מעבר למצופה', 'She always goes the extra mile for her clients.', 'C1', 127),
  ('back to square one', 'idiom', 'חזרה לנקודת ההתחלה', 'The deal collapsed, so we''re back to square one.', 'C1', 128),
  ('the tip of the iceberg', 'idiom', 'קצה הקרחון', 'These complaints are only the tip of the iceberg.', 'C1', 129),
  ('a Pyrrhic victory', 'idiom', 'ניצחון פירוס, ניצחון שמחירו גבוה מדי', 'Winning the lawsuit was a Pyrrhic victory: the legal fees ruined them.', 'C2', 130),
  ('a vested interest', 'idiom', 'אינטרס אישי בתוצאה', 'Oil companies have a vested interest in delaying the change.', 'C2', 131),
  ('par for the course', 'idiom', 'צפוי, דבר שקורה תמיד', 'Delays are par for the course on this train line.', 'C2', 132),
  ('muddy the waters', 'idiom', 'לסבך ולבלבל את התמונה', 'His late statement only muddied the waters.', 'C2', 133),
  ('hinge on', 'phrasal_verb', 'להיות תלוי ב-', 'The whole case hinges on one witness.', 'C2', 134),
  ('devil''s advocate', 'idiom', 'פרקליט השטן, מי שמציג עמדה נגדית לצורך הדיון', 'Let me play devil''s advocate for a moment.', 'C2', 135)
) as i(phrase, type, meaning_he, example_en, lvl, sort_order)
where not exists (select 1 from public.idioms_phrasal_verbs x where lower(x.phrase) = lower(i.phrase));

update public.writing_prompts set title_he = 'אוכל שאוהבים ואוכל שפחות' where title_he = 'האוכל שאני אוהב';
update public.idioms_phrasal_verbs set meaning_he = 'בהרגשה לא טובה' where meaning_he = 'לא מרגיש טוב';

